// oxtty/xterm: the Rust front end (xterm_web.js, generated by wasm-bindgen from crates/oxtty-web) over the oxtty
// engine (index.js). `init()` loads both WebAssembly modules; everything else is the generated binding.
import { init as initEngine } from './index.js';
import initFrontEnd from './xterm_web.js';

export * from './xterm_web.js';

/** Loads the engine and the front end once. Sources default to the files next to this module. */
export async function init(engine, frontEnd) {
  await Promise.all([initEngine(engine), initFrontEnd(frontEnd === undefined ? undefined : { module_or_path: frontEnd })]);
}
